						updated_at = now()
					WHERE organization_id = ${bindingIdentity.organizationId}
						AND client_id = ${bindingIdentity.clientId}
						AND user_id = ${bindingIdentity.userId}
						AND conversation_key = ${bindingIdentity.conversationKey}
