import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		close = bridge.close;
	},
}));

const originalParent = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenAi = Object.getOwnPropertyDescriptor(window, "openai");

function restore(
	name: "parent" | "openai",
	descriptor: PropertyDescriptor | undefined,
) {
	if (descriptor) Object.defineProperty(window, name, descriptor);
	else Reflect.deleteProperty(window, name);
}

describe("review reproducer", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.connect.mockResolvedValue(undefined);
	});
	afterEach(() => {
		restore("parent", originalParent);
		restore("openai", originalOpenAi);
	});

	it("keeps a restored approval card correlated with its full replay", async () => {
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: Object.assign(new EventTarget(), {
				location: { origin: "https://portable.example" },
			}),
		});
		bridge.callServerTool.mockImplementation(async ({ name }) =>
			name === "restore_lobu_app_result"
				? {
						isError: false,
						structuredContent: {
							found: true,
							tool_name: "render_lobu_view",
							data: {
								version: 1,
								title: "Review",
								actions: [
									{ id: "review", href: "https://lobu.ai/runs/1" },
								],
							},
							view_state: { "details.open": true },
						},
					}
				: { isError: false },
		);

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState } = useMcpApp<{
				actions: Array<{ id: string }>;
			}>();
			return (
				<>
					<span>{data?.actions.map((action) => action.id).join(",") ?? "none"}</span>
					<span>open:{String(viewState["details.open"])}</span>
				</>
			);
		}
		render(
			<Provider devMock={{}}>
				<Probe />
			</Provider>,
		);
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: {},
					_meta: {
						"lobu/mcp-app-snapshot-capability": "cap",
						"lobu/approval-capability": "approval",
					},
				});
			}
		});
		expect(await screen.findByText("review")).toBeInTheDocument();
		expect(await screen.findByText("open:true")).toBeInTheDocument();

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: {
						version: 1,
						title: "Review",
						actions: [
							{ id: "approve", tool: "resolve_lobu_approval" },
							{ id: "review", href: "https://lobu.ai/runs/1" },
						],
					},
				});
			}
		});
		expect(await screen.findByText("approve,review")).toBeInTheDocument();
		await waitFor(() => expect(screen.getByText("open:true")).toBeInTheDocument());
	});
});

